// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Client project session – a framework-free state machine that owns the live document, its revision,
//          the debounced save queue, retries, conflicts, status and the per-project view state.

import type { ProjectRecord } from '#/server/projects.server'
import type { ProjectData, ProjectView } from './project'
import { TransportError, type CallOptions, type ProjectTransport } from './projectTransport'

/**
 * saved/pending/saving – normal cycle; retrying – transient failure, will retry by itself;
 * failed – the server rejected the save (see `error`), retried a few times then left until the next edit;
 * conflict – another tab/colleague saved first (see `conflict`), nothing is saved until resolveConflict();
 * missing – the project was deleted elsewhere, local edits are kept but cannot be saved.
 */
export type SaveStatus = 'saved' | 'pending' | 'saving' | 'retrying' | 'failed' | 'conflict' | 'missing'

export interface SessionState {
  data: ProjectData
  view: ProjectView
  status: SaveStatus
  /** Something (document or view) is not yet on the server. */
  unsaved: boolean
  /** Message of the last failed save (status retrying/failed). */
  error: string | null
  /** The newer server version our save collided with. */
  conflict: ProjectRecord | null
  savedAt: string
}

export interface Timers {
  setTimeout: (fn: () => void, ms: number) => unknown
  clearTimeout: (handle: unknown) => void
}

const DEBOUNCE_MS = 600
const RETRY_BASE_MS = 5_000
const RETRY_MAX_MS = 60_000
/** Attempts of a save the server rejected (not transient) before waiting for the next edit. */
const REJECTED_ATTEMPTS = 3

// Saves still running per project id – also those of sessions already disposed (the editor was left).
const running = new Map<string, Set<Promise<unknown>>>()

function track(projectId: string, promise: Promise<unknown>) {
  const set = running.get(projectId) ?? new Set()
  running.set(projectId, set)
  const done = promise.catch(() => {})
  set.add(done)
  void done.then(() => {
    set.delete(done)
    if (!set.size) running.delete(projectId)
  })
}

/**
 * Resolves once no save of this project is running. The route loader awaits it before fetching, so coming back
 * to a project right after leaving it loads the revision the last save produced (instead of self-conflicting).
 */
export async function savesSettled(projectId: string): Promise<void> {
  for (let set = running.get(projectId); set?.size; set = running.get(projectId)) await Promise.all(set)
}

export function createProjectSession(initial: ProjectRecord, transport: ProjectTransport, timers: Timers = defaultTimers()) {
  let state: SessionState = {
    data: initial.data,
    view: initial.view,
    status: 'saved',
    unsaved: false,
    error: null,
    conflict: null,
    savedAt: initial.updatedAt,
  }
  let revision = initial.revision
  let timer: unknown
  // Every edit bumps `editSeq`; the document is persisted when `savedSeq` caught up with it.
  let editSeq = 0
  let savedSeq = 0
  let inFlight: Promise<void> | null = null
  // Saving is impossible until the user acts (conflict, or the project was deleted elsewhere).
  let missing = false
  let conflict: ProjectRecord | null = null
  const blocked = () => missing || conflict !== null
  // Failed attempts in a row (reset by success and by a new edit after giving up).
  let failures = 0
  let lastFailure: TransportError | null = null

  // View state: its own debounced queue, no revision (last write wins), never blocks or conflicts.
  let viewSeq = 0
  let viewSavedSeq = 0
  let viewInFlight: Promise<void> | null = null
  let viewTimer: unknown
  let viewFailures = 0

  const dirty = () => editSeq !== savedSeq
  const viewDirty = () => viewSeq !== viewSavedSeq
  const listeners = new Set<() => void>()
  const set = (patch: Partial<SessionState>) => {
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
    // Changes: Only document edits count as unsaved (arms the leave-page prompt); view state is flushed on page hide.
    const next = { ...state, ...patch, unsaved: dirty() }
    if (Object.keys(next).every((k) => next[k as keyof SessionState] === state[k as keyof SessionState])) return
    state = next
    listeners.forEach((l) => l())
  }

  let disposed = false
  const schedule = (ms: number) => {
    timers.clearTimeout(timer)
    if (disposed) return
    timer = timers.setTimeout(() => void flush(), ms)
  }

  const saveOnce = async (opts?: CallOptions) => {
    const seq = editSeq
    const data = state.data
    set({ status: 'saving' })
    try {
      const res = await transport.save({ id: initial.id, data, baseRevision: revision }, opts)
      failures = 0
      lastFailure = null
      if (res.status === 'saved') {
        revision = res.revision
        savedSeq = seq
        set({ savedAt: res.updatedAt })
      } else if (res.status === 'conflict') conflict = res.project
      else missing = true
    } catch (err) {
      failures++
      lastFailure = err instanceof TransportError ? err : new TransportError(err instanceof Error ? err.message : String(err), true)
    }
  }

  const flush = async (opts?: CallOptions): Promise<void> => {
    timers.clearTimeout(timer)
    if (inFlight) {
      await inFlight
      return flush(opts)
    }
    if (blocked() || !dirty()) return
    inFlight = saveOnce(opts)
    track(initial.id, inFlight)
    await inFlight
    inFlight = null
    if (missing) set({ status: 'missing' })
    else if (conflict) set({ status: 'conflict', conflict })
    else if (lastFailure) {
      const giveUp = !lastFailure.retryable && failures >= REJECTED_ATTEMPTS
      set({ status: lastFailure.retryable ? 'retrying' : 'failed', error: lastFailure.message })
      if (!giveUp) schedule(Math.min(RETRY_BASE_MS * 2 ** (failures - 1), RETRY_MAX_MS))
    } else if (dirty()) {
      set({ status: 'pending' })
      schedule(DEBOUNCE_MS)
    } else set({ status: 'saved', error: null })
  }

  /** Replace the local document by a server record (local edits are gone – callers make sure that is intended). */
  const adopt = (record: ProjectRecord) => {
    timers.clearTimeout(timer)
    revision = record.revision
    savedSeq = editSeq
    conflict = null
    failures = 0
    lastFailure = null
    set({ data: record.data, status: 'saved', error: null, conflict: null, savedAt: record.updatedAt })
  }

  const scheduleView = (ms: number) => {
    timers.clearTimeout(viewTimer)
    if (!disposed) viewTimer = timers.setTimeout(() => void flushView(), ms)
  }

  const flushView = async (opts?: CallOptions): Promise<void> => {
    timers.clearTimeout(viewTimer)
    if (viewInFlight) {
      await viewInFlight
      return flushView(opts)
    }
    if (!viewDirty()) return
    const seq = viewSeq
    let retryIn = 0
    viewInFlight = (async () => {
      try {
        await transport.saveView({ id: initial.id, view: state.view }, opts)
        viewSavedSeq = seq
        viewFailures = 0
      } catch (err) {
        viewFailures++
        const retryable = !(err instanceof TransportError) || err.retryable
        // It is only UI state: after a few rejected attempts stop insisting (and stop the unload warning).
        if (!retryable && viewFailures >= REJECTED_ATTEMPTS) viewSavedSeq = seq
        else retryIn = Math.min(RETRY_BASE_MS * 2 ** (viewFailures - 1), RETRY_MAX_MS)
      }
    })()
    track(initial.id, viewInFlight)
    await viewInFlight
    viewInFlight = null
    set({})
    if (retryIn) scheduleView(retryIn)
    else if (viewDirty()) scheduleView(DEBOUNCE_MS)
  }

  // Persist local edits or explain (in Slovak, for a toast) why the caller must not go on.
  const ensureSaved = async () => {
    await flush()
    if (conflict) throw new Error('Najprv vyrieš konflikt verzií – tvoje zmeny zatiaľ nie sú uložené.')
    if (missing) throw new Error('Projekt bol medzitým zmazaný – tvoje zmeny nie je kam uložiť.')
    if (dirty()) {
      const reason = lastFailure ? ` (${lastFailure.message})` : ''
      throw new Error(`Neuložené zmeny sa nepodarilo uložiť${reason}. Skús to znova o chvíľu.`)
    }
  }

  // Run a server call that replaces the document; it occupies the save slot so no save overlaps it.
  const replaceWith = async (call: () => Promise<ProjectRecord | null>, goneMessage: string) => {
    await ensureSaved()
    const seq = editSeq
    let result: ProjectRecord | null = null
    const op = (async () => {
      result = await call()
    })()
    inFlight = op.catch(() => {})
    track(initial.id, inFlight)
    try {
      await op
    } finally {
      inFlight = null
    }
    const record = result as ProjectRecord | null
    if (!record) throw new Error(goneMessage)
    if (editSeq === seq) return adopt(record)
    // The user typed while the server replaced the document: keep both and let them choose.
    conflict = record
    set({ status: 'conflict', conflict: record })
  }

  return {
    /** Immutable snapshot – a new object whenever anything changed (fits useSyncExternalStore). */
    getState: () => state,
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => void listeners.delete(listener)
    },
    /** Save pending edits now; resolves true when everything is on the server. */
    async flushNow() {
      await Promise.all([flush(), flushView()])
      return !dirty()
    },
    /** The page is being hidden or closed: save everything now, in requests that may outlive the page. */
    pageHidden() {
      const opts = { keepalive: true }
      void flush(opts)
      void flushView(opts)
    },
    /** Change the per-project view state (saved debounced, independent of the document). */
    updateView(fn: (v: ProjectView) => ProjectView) {
      viewSeq++
      set({ view: fn(state.view) })
      if (!viewInFlight && !viewFailures) scheduleView(DEBOUNCE_MS)
    },
    /** A record fetched again (route loader). Adopted only when newer and nothing local is pending. */
    receive(record: ProjectRecord) {
      if (!viewDirty() && !viewInFlight) set({ view: record.view })
      if (record.revision <= revision || dirty() || inFlight || blocked()) return
      adopt(record)
    },
    /** The editor goes away: save what is pending right now (tracked by savesSettled) and stop timers. */
    dispose() {
      disposed = true
      timers.clearTimeout(timer)
      timers.clearTimeout(viewTimer)
      track(initial.id, Promise.all([flush(), flushView()]))
    },
    /** Undo dispose() when React mounts the same editor again (StrictMode, Activity). */
    resume() {
      disposed = false
      if (dirty() && !blocked() && !inFlight) schedule(DEBOUNCE_MS)
      if (viewDirty() && !viewInFlight) scheduleView(DEBOUNCE_MS)
    },
    /** Restore a snapshot (the server stores the current state in history first). */
    restoreVersion: (snapshotId: number) =>
      replaceWith(() => transport.restore({ id: initial.id, snapshotId }), 'Verzia už neexistuje'),
    /** Replace the document by imported data; `label` names the history entry of the current state. */
    importData: (data: ProjectData, label: string) =>
      replaceWith(() => transport.replace({ id: initial.id, data, label }), 'Projekt už neexistuje'),
    /** Store the current (saved) state as a named version. */
    async saveNamedVersion(label: string) {
      await ensureSaved()
      const snapshot = await transport.createSnapshot({ id: initial.id, label })
      if (!snapshot) throw new Error('Projekt už neexistuje')
      return snapshot
    },
    /** theirs = load the server version (drops local edits); mine = overwrite the server with the local version. */
    async resolveConflict(choice: 'theirs' | 'mine') {
      if (!conflict) return
      if (choice === 'theirs') return adopt(conflict)
      revision = conflict.revision
      conflict = null
      set({ status: 'pending', conflict: null })
      await flush()
    },
    /** Change the document; saved after a short pause in editing. */
    edit(fn: (d: ProjectData) => ProjectData) {
      editSeq++
      // Not while blocked or a request runs (it reschedules), nor during a transient-failure backoff;
      // after a rejected save a new edit is a fresh round of attempts.
      const start = !blocked() && !inFlight && !lastFailure?.retryable
      if (start) failures = 0
      set({ data: fn(state.data), ...(start ? { status: 'pending' as const } : {}) })
      if (start) schedule(DEBOUNCE_MS)
    },
  }
}

function defaultTimers(): Timers {
  return {
    setTimeout: (fn, ms) => globalThis.setTimeout(fn, ms),
    clearTimeout: (h) => globalThis.clearTimeout(h as ReturnType<typeof setTimeout>),
  }
}
